import fs from 'fs';
import path from 'path';

const TRANSLATIONS_DIR = path.join(process.cwd(), 'public/locales');

interface TourTranslations {
  tourName?: string;
  description?: string;
  duration?: string;
  includes?: string;
  meetingPoint?: string;
}

export async function saveTourTranslationsToJson(
  tourSlug: string,
  translations: { es: TourTranslations; en: TourTranslations }
): Promise<void> {
  for (const lang of ['es', 'en'] as const) {
    const langDir = path.join(TRANSLATIONS_DIR, lang);
    const filePath = path.join(langDir, 'tours.json');

    // Cargar archivo existente o crear nuevo
    let existingTranslations = {};
    if (fs.existsSync(filePath)) {
      try {
        existingTranslations = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      } catch (e) {
        existingTranslations = {};
      }
    }

    // Actualizar solo las claves del tour
    for (const [key, value] of Object.entries(translations[lang] || {})) {
      if (value) {
        existingTranslations[`tours.${tourSlug}.${key}`] = value;
      }
    }

    // Escribir archivo
    fs.writeFileSync(filePath, JSON.stringify(existingTranslations, null, 2));
  }

  console.log(`[i18n] Guardadas traducciones para tour: ${tourSlug}`);
}

export async function deleteTourTranslationsFromJson(tourSlug: string): Promise<void> {
  for (const lang of ['es', 'en'] as const) {
    const filePath = path.join(TRANSLATIONS_DIR, lang, 'tours.json');

    if (fs.existsSync(filePath)) {
      const translations = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

      // Eliminar claves del tour
      for (const key of Object.keys(translations)) {
        if (key.startsWith(`tours.${tourSlug}.`)) {
          delete translations[key];
        }
      }

      fs.writeFileSync(filePath, JSON.stringify(translations, null, 2));
    }
  }
}
